    static string Tenant(HttpContext c) => ((PrincipalContext)c.Items["principal"]!).TenantId; static string Actor(HttpContext c) => ((PrincipalContext)c.Items["principal"]!).Subject; static IResult Ok(HttpContext c, object x) => Results.Ok(new ApiEnvelope<object>(x, new(c.TraceIdentifier, "1.0")));
