    static async Task<IResult> CreateInvestigation(InvestigationCreate x, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) => Results.Created("/api/v1/investigations", new ApiEnvelope<object>(await s.CreateAsync(Tenant(c), Actor(c), x.Title, x.Description, x.Priority, x.Owner, x.EndpointIds ?? [], x.IncidentIds ?? [], x.AlertIds ?? [], x.Tags ?? [], ct), new(c.TraceIdentifier, "1.0")));
