    static async Task<IResult> Status(Guid id, StatusRequest x, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) => Ok(c, await s.StatusAsync(Tenant(c), Actor(c), id, x.Status, x.Reason, ct));
    static async Task<IResult> LinkCollection(Guid id, CollectionLinkRequest x, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) { var value = new InvestigationCollection(x.CollectionId, id, Tenant(c), x.EndpointId, x.AgentInstallationId, x.ProfileId, x.ProfileVersion, x.ProfileHash, x.State, x.RequestedAt, null, null, x.RequestedItems, 0, 0, 0, 0, 0, 0, null, null, x.RecollectionOf, x.IdempotencyKey); return Ok(c, await s.LinkCollectionAsync(Tenant(c), Actor(c), id, value, ct)); }
    static async Task<IResult> ImportCollection(Guid id, Guid collection, HttpContext c, ForensicWorkspaceService s, IResponseActionRepository responses, CancellationToken ct)
    {
        var page = await responses.SearchAsync(Tenant(c), null, null, 200, null, ct); var action = page.Items.FirstOrDefault(x => x.ActionType == ForensicCollectionSafety.ActionType && x.Parameters.TryGetProperty("collectionId", out var p) && p.TryGetGuid(out var found) && found == collection); if (action is null) return Results.NotFound(); ForensicCollectionResult? result = null; try { result = action.Result?.StructuredResult.Deserialize<ForensicCollectionResult>(Json); } catch (JsonException) { }
        var requested = action.Parameters.GetProperty("requestedArtifacts").GetArrayLength(); var profile = ForensicWorkspaceSafety.Profiles.FirstOrDefault(x => x.ProfileId == action.Parameters.GetProperty("profileId").GetString()); var link = new InvestigationCollection(collection, id, Tenant(c), action.EndpointId, action.AgentInstallationId, profile?.ProfileId ?? action.Parameters.GetProperty("profileId").GetString()!, profile?.Version ?? 1, profile?.ProfileHash ?? action.Parameters.GetProperty("profileHash").GetString()!, result?.State.ToString() ?? action.State.ToString(), action.RequestedAt, action.StartedAt, action.CompletedAt, requested, result?.CollectedItems ?? 0, result?.FailedItems ?? 0, result?.SkippedItems ?? 0, result?.BytesCollected ?? 0, result?.BytesCollected ?? 0, result?.Items.Sum(x => x.ArtifactId is null ? 0 : 1) ?? 0, result?.FailureReason, result?.FailureReason, null, $"response-action:{action.ResponseActionId:D}"); await s.LinkCollectionAsync(Tenant(c), Actor(c), id, link, ct);
        if (result is not null) foreach (var item in result.Items) { var artifactId = item.ArtifactId; var stored = artifactId is not null && item.Sha256 is { Length: 64 }; var responseArtifact = stored ? action.Result?.Artifacts.FirstOrDefault(x => x.ArtifactId == artifactId!.Value) : null; var manifestArtifact = action.Result?.Artifacts.FirstOrDefault(x => x.ArtifactId == result.ManifestArtifactId); var evidence = new ForensicWorkspaceArtifact(item.EvidenceItemId, id, collection, Tenant(c), action.EndpointId, action.AgentInstallationId, item.ArtifactType.ToString(), item.SourceObject, item.AcquisitionMethod, item.AcquisitionToolVersion, item.SourceObject, item.NativeIdentity, null, item.ObservedAt, item.AcquisitionStartedAt, item.AcquisitionCompletedAt, item.AcquiredSize, stored ? item.AcquiredSize : 0, stored ? 1 : 0, stored ? item.Sha256! : new string('0', 64), stored && responseArtifact is not null, stored ? responseArtifact!.ObjectId : $"unavailable:{item.EvidenceItemId:D}", responseArtifact?.MediaType ?? "application/octet-stream", stored ? EvidenceIntegrityStatus.NotVerified : EvidenceIntegrityStatus.Missing, null, null, EvidenceParseStatus.NotRequested, "NotRequested", null, item.RequestId, [], [], [], false, item.State.ToString(), item.FailureReason, item.FailureReason, DateTimeOffset.UtcNow, manifestArtifact?.ObjectId, result.ManifestHash); await s.AddArtifactAsync(Tenant(c), "system:collection-import", evidence, ct); }
        return Ok(c, new { collectionId = collection, importedArtifacts = result?.Items.Length ?? 0, state = result?.State.ToString() ?? action.State.ToString() });
    }
    static async Task<IResult> Collections(Guid id, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) => Ok(c, (await s.GetAsync(Tenant(c), ct)).Collections.Where(x => x.InvestigationId == id).OrderByDescending(x => x.RequestedAt));
    static EvidenceSearch Search(HttpContext c) { var q = c.Request.Query; return new(q["text"], Guid.TryParse(q["investigationId"], out var i) ? i : null, Guid.TryParse(q["collectionId"], out var col) ? col : null, Guid.TryParse(q["endpointId"], out var e) ? e : null, q["evidenceType"], q["hash"], q["state"], q["parser"], q["tag"], bool.TryParse(q["bookmarked"], out var b) ? b : null, int.TryParse(q["limit"], out var n) ? n : 100, q["cursor"]); }
