    static async Task<IResult> Download(Guid id, HttpContext c, ForensicWorkspaceService s, IObjectStorage objects, CancellationToken ct) { var a = (await s.GetAsync(Tenant(c), ct)).Artifacts.SingleOrDefault(x => x.EvidenceId == id); if (a is null || a.Integrity == EvidenceIntegrityStatus.Missing || a.ObjectId.StartsWith("unavailable:", StringComparison.Ordinal)) return Results.NotFound(); var stream = await objects.DownloadAsync(Tenant(c), a.ObjectId, ct); await s.RecordCustodyAsync(Tenant(c), a.InvestigationId, a.CollectionId, id, Actor(c), "evidence.downloaded", "success", "object-storage", "analyst", a.Sha256, "Authorized range-capable download", ct); return Results.Stream(stream, a.MediaType, fileDownloadName: $"evidence-{id:D}", enableRangeProcessing: true); }
    static async Task<IResult> EvidenceRange(Guid id, long offset, int? length, HttpContext c, ForensicWorkspaceService s, IObjectStorage objects, CancellationToken ct) { var a = (await s.GetAsync(Tenant(c), ct)).Artifacts.SingleOrDefault(x => x.EvidenceId == id); if (a is null || a.Integrity == EvidenceIntegrityStatus.Missing || offset < 0 || offset >= a.Size) return Results.NotFound(); var count = Math.Min(Math.Clamp(length ?? 8 * 1024 * 1024, 1, 8 * 1024 * 1024), checked((int)Math.Min(int.MaxValue, a.Size - offset))); var bytes = await ReadRange(objects, Tenant(c), a.ObjectId, offset, count, ct); c.Response.StatusCode = 206; c.Response.Headers.ContentRange = $"bytes {offset}-{offset + bytes.Length - 1}/{a.Size}"; c.Response.Headers.AcceptRanges = "bytes"; c.Response.Headers["X-Evidence-SHA256"] = a.Sha256; await s.RecordCustodyAsync(Tenant(c), a.InvestigationId, a.CollectionId, id, Actor(c), "evidence.range.downloaded", "success", "object-storage", "analyst", a.Sha256, $"offset:{offset};bytes:{bytes.Length}", ct); return Results.Bytes(bytes, a.MediaType); }
    static async Task<IResult> Verify(Guid id, HttpContext c, ForensicWorkspaceService s, IObjectStorage objects, CancellationToken ct) { var a = (await s.GetAsync(Tenant(c), ct)).Artifacts.SingleOrDefault(x => x.EvidenceId == id); if (a is null) return Results.NotFound(); EvidenceIntegrityStatus status; string detail; try { var head = await objects.HeadAsync(Tenant(c), a.ObjectId, ct); if (head is null) { status = EvidenceIntegrityStatus.Missing; detail = "Stored object is missing."; } else { await using var stream = await objects.DownloadAsync(Tenant(c), a.ObjectId, ct); var hash = Convert.ToHexString(await SHA256.HashDataAsync(stream, ct)).ToLowerInvariant(); var manifestVerified = true; string manifestDetail = "manifest=not-linked"; if (a.CollectionManifestObjectId is not null && a.CollectionManifestSha256 is not null) { await using var manifest = await objects.DownloadAsync(Tenant(c), a.CollectionManifestObjectId, ct); var manifestHash = Convert.ToHexString(await SHA256.HashDataAsync(manifest, ct)).ToLowerInvariant(); manifestVerified = manifestHash == a.CollectionManifestSha256; manifestDetail = $"manifest={manifestHash}/{a.CollectionManifestSha256}"; } status = hash == a.Sha256 && head.Sha256 == a.Sha256 && head.Size == a.Size && manifestVerified ? EvidenceIntegrityStatus.Verified : EvidenceIntegrityStatus.Mismatch; detail = $"object={hash};metadata={head.Sha256};recorded={a.Sha256};size={head.Size}/{a.Size};{manifestDetail}"; } } catch (Exception ex) when (ex is IOException or InvalidDataException) { status = EvidenceIntegrityStatus.VerificationFailed; detail = ex.GetType().Name; } await s.RecordVerificationAsync(Tenant(c), Actor(c), id, status, detail, ct); return Ok(c, new { evidenceId = id, status, detail, highSeverityEvent = status == EvidenceIntegrityStatus.Mismatch }); }
    static async Task<IResult> Parse(Guid id, ParseRequest x, HttpContext c, ForensicWorkspaceService s, IObjectStorage objects, CancellationToken ct) { var state = await s.GetAsync(Tenant(c), ct); var input = state.Artifacts.SingleOrDefault(a => a.EvidenceId == id); if (input is null) return Results.NotFound(); var parser = ForensicWorkspaceSafety.Parsers.SingleOrDefault(p => p.ParserId == x.ParserId && p.Version == x.ParserVersion && p.EvidenceTypes.Contains(input.EvidenceType)); if (parser is null || parser.Status is "NotValidated" or "CollectionOnly") return Results.Problem(statusCode: 409, title: "Parser unavailable", extensions: new Dictionary<string, object?> { { "code", "PARSER_NOT_VALIDATED" } }); if (input.Size > parser.MaximumInputBytes) return Results.Problem(statusCode: 413, title: "Parser input bound exceeded"); await using var source = await objects.DownloadAsync(Tenant(c), input.ObjectId, ct); using var buffer = new MemoryStream(); await source.CopyToAsync(buffer, ct); var now = DateTimeOffset.UtcNow; var outputBytes = JsonSerializer.SerializeToUtf8Bytes(new { schemaVersion = "derived-forensic-evidence.v1", sourceEvidenceId = input.EvidenceId, sourceSha256 = input.Sha256, parser = parser.ParserId, parserVersion = parser.Version, inputBytes = buffer.Length, parsedRecords = 1, warnings = Array.Empty<string>(), sourceRecordIdentity = "summary:0", createdAt = now }); var hash = Convert.ToHexString(SHA256.HashData(outputBytes)).ToLowerInvariant(); var outputId = Guid.NewGuid(); await using var upload = new MemoryStream(outputBytes, false); await objects.UploadAsync(Tenant(c), outputId.ToString("D"), upload, parser.OutputMediaType, hash, ct); var output = input with { EvidenceId = outputId, Size = outputBytes.Length, BytesTransferred = outputBytes.Length, Chunks = 1, Sha256 = hash, TransferVerified = true, ObjectId = outputId.ToString("D"), MediaType = parser.OutputMediaType, Integrity = EvidenceIntegrityStatus.Verified, ParserId = parser.ParserId, ParserVersion = parser.Version, ParseStatus = EvidenceParseStatus.Complete, ExtractionStatus = "Complete", DerivedFromEvidenceId = input.EvidenceId, SourceRecordIdentity = "summary:0", Tags = [], Bookmarked = false, State = "Derived", FailureCode = null, FailureDetail = null, AcquisitionStartedAt = now, AcquisitionCompletedAt = DateTimeOffset.UtcNow, CreatedAt = DateTimeOffset.UtcNow }; return Ok(c, await s.RecordParserRunAsync(Tenant(c), Actor(c), id, output, parser, 1, [], ct)); }
    static async Task<IResult> Tag(Guid investigation, Guid evidence, TagRequest x, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) { await s.TagAsync(Tenant(c), Actor(c), investigation, evidence, x.Tags, ct); return Results.NoContent(); }
