    static async Task<IResult> Notes(Guid id, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) => Ok(c, (await s.GetAsync(Tenant(c), ct)).Notes.Where(x => x.InvestigationId == id).OrderByDescending(x => x.CreatedAt));
    static async Task<IResult> Bookmarks(Guid id, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) => Ok(c, (await s.GetAsync(Tenant(c), ct)).Bookmarks.Where(x => x.InvestigationId == id).OrderByDescending(x => x.CreatedAt));
    static async Task<IResult> Timeline(Guid id, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) { var q = c.Request.Query; var state = await s.GetAsync(Tenant(c), ct); var items = state.Timeline.Where(x => x.InvestigationId == id && (!Guid.TryParse(q["endpointId"], out var endpoint) || x.EndpointId == endpoint) && (string.IsNullOrWhiteSpace(q["eventType"]) || x.EventType == q["eventType"]) && (!DateTimeOffset.TryParse(q["from"], out var from) || x.OccurredAt >= from) && (!DateTimeOffset.TryParse(q["to"], out var to) || x.OccurredAt <= to)).OrderByDescending(x => x.OccurredAt).Take(Math.Clamp(int.TryParse(q["limit"], out var n) ? n : 200, 1, 1000)); return Ok(c, items); }
    static async Task<IResult> Entities(Guid id, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) { var state = await s.GetAsync(Tenant(c), ct); var evidence = state.Artifacts.Where(x => x.InvestigationId == id).ToArray(); var entities = evidence.SelectMany(x => x.RelatedEntities.Select(e => new { entityId = e, evidenceId = x.EvidenceId, x.EndpointId, x.EvidenceType })).Take(1000).ToArray(); var hashes = evidence.Where(x => x.Integrity != EvidenceIntegrityStatus.Missing).GroupBy(x => x.Sha256).Select(x => new { sha256 = x.Key, endpoints = x.Select(v => v.EndpointId).Distinct().ToArray(), evidence = x.Select(v => v.EvidenceId).ToArray() }).Where(x => x.endpoints.Length > 1).Take(100).ToArray(); return Ok(c, new { entities, crossEndpointHashes = hashes, unsupportedEdgesAdded = 0 }); }
