    static async Task<IResult> Hold(Guid id, HoldRequest x, HttpContext c, ForensicWorkspaceService s, ICapacityRetentionRepository retention, CancellationToken ct) { var state = await s.GetAsync(Tenant(c), ct); if (!state.Investigations.Any(v => v.InvestigationId == id)) return Results.NotFound(); var hold = await retention.PutHoldAsync(Tenant(c), Actor(c), new("investigation", "forensic-evidence", id.ToString("D"), x.Reason, x.ExpiresAt), ct); await s.RecordHoldAsync(Tenant(c), Actor(c), id, null, hold.HoldId, x.Reason, ct); return Ok(c, hold); }
