    static async Task<IResult> AiSummary(Guid id, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) { var state = await s.GetAsync(Tenant(c), ct); if (!state.Investigations.Any(x => x.InvestigationId == id)) return Results.NotFound(); var selected = state.Artifacts.Where(x => x.InvestigationId == id).OrderByDescending(x => x.Bookmarked).ThenByDescending(x => x.RelatedFindings.Length).ThenByDescending(x => x.CreatedAt).Take(20).ToArray(); var citations = selected.Select(x => $"EVID-{x.EvidenceId:D}").ToArray(); var body = selected.Length == 0 ? "Unknown: no authorized evidence is available for analysis." : $"Observed: {selected.Length} bounded evidence item(s) were selected. Strongest items: {string.Join(", ", selected.Take(5).Select(x => $"{x.EvidenceType} [{"EVID-" + x.EvidenceId.ToString("D")}]"))}. Missing or unavailable items remain explicit; this draft does not execute response."; var note = await s.NoteAsync(Tenant(c), "ai:local-evidence", id, "investigation", id.ToString("D"), body, true, false, citations, ct); return Ok(c, new { note, selectedEvidence = selected.Select(x => x.EvidenceId), truncated = state.Artifacts.Count(x => x.InvestigationId == id) > selected.Length, provider = "local-evidence/local-evidence-v1", readOnly = true }); }
