    static async Task<IResult> Exports(Guid id, HttpContext c, ForensicWorkspaceService s, CancellationToken ct) => Ok(c, (await s.GetAsync(Tenant(c), ct)).Exports.Where(x => x.InvestigationId == id).OrderByDescending(x => x.CreatedAt));
